/**
 * Mark a response whose body vinext constructed from a fully in-memory string
 * or byte array, as opposed to a body handed back by user code, which could
 * still be producing. With no producer left, no `after()` call can originate
 * from this body.
 */
export declare function markFullyBufferedBody(response: Response): Response;
export declare function isFullyBufferedBody(response: Response): boolean;
export declare function preserveFullyBufferedBodyMetadata(source: Response, target: Response): Response;
//#endregion